style.css:
/* Roblox — Victoria's Secret Angel */
:root {
  /* change these colours to customise */
  --my-pink: #f6c5d5;
  --my-light: #fff1f6;
  --my-white: #ffffff;
  --my-text: #9b526e;
}

/* dreamy pink background */
html,
body {
  background: linear-gradient(
    135deg,
    #fff5f8,
    #f9dce8,
    #ffffff,
    #f4c3d6
  ) !important;
  color: var(--my-text) !important;
}

/* elegant typography */
body {
  font-family: Georgia, "Times New Roman", serif !important;
}

/* links */
a {
  color: #c46b91 !important;
}

/* buttons */
button,
[role="button"] {
  background: #f5d0df !important;
  color: #914b69 !important;
  border: 1px solid #efb5cc !important;
  border-radius: 20px !important;
}

/* soft hover */
button:hover,
[role="button"]:hover {
  background: #fff0f6 !important;
}

/* cards */
[class*="card"],
[class*="Card"] {
  border-radius: 16px !important;
  border: 1px solid #f5d5e2 !important;
  box-shadow: 0 4px 15px #e9a9c522 !important;
}

/* soft image corners */
img {
  border-radius: 10px !important;
}
